function sanitizeEmail(rawEmail) {
  let email = rawEmail.trim().toLowerCase();

  // Common TLD typo corrections
  const corrections = {
    ".cmo": ".com",
    ".cpm": ".com",
    ".cim": ".com",
    ".cok": ".com",
    ".orh": ".org",
    ".ogr": ".org",
    ".con": ".com",
    ".edh": ".edu",
    ".esu": ".edu"
