function sanitizeEmail(rawEmail) {
  let email = rawEmail.trim().toLowerCase();

  // Common TLD typo corrections
  const corrections = {
    ".cmo": ".com",
    ".cpm": ".com",
    ".cim": ".com",
    ".cok": ".com",
    ".orh": ".org",
    ".ogr": ".org",
    ".con": ".com",
    ".edh": ".edu",
    ".esu": ".edu"
  };
  for (const [typo, fix] of Object.entries(corrections)) {
    if (email.endsWith(typo)) {
      email = email.slice(0, -typo.length) + fix;
      break;
    }
  }
  if (validator.isEmail(email)) {
    return email;
  }
  return null;
}

